/** Date filters shared by the dashboard and embeddable aggregation API. Dates use UTC. */
export type AnalyticsRangeParams = {
	range?: "today" | "7d" | "30d" | "custom";
	start?: string;
	end?: string;
	path?: string;
	limit?: number;
};

/** One UTC day of traffic. */
export type AnalyticsSeriesPoint = {
	date: string;
	pageViews: number;
	visitors: number;
};

/** Page traffic and daily page-view counts for a sparkline. */
export type AnalyticsTopPage = {
	path: string;
	views: number;
	visitors: number;
	trend: number[];
};

/** External referrer host and its traffic. */
export type AnalyticsTopReferrer = {
	referrer: string;
	views: number;
	visitors: number;
};

/** Custom event name and number of occurrences. */
export type AnalyticsTopEvent = {
	name: string;
	count: number;
};

/** Aggregated traffic. Duration is in seconds and bounce rate is a percentage. */
export type AnalyticsDashboardStats = {
	uniqueVisitors: number;
	pageViews: number;
	bounceRate: number;
	sessionDuration: number;
	series: AnalyticsSeriesPoint[];
	topPages: AnalyticsTopPage[];
	topReferrers: AnalyticsTopReferrer[];
	topEvents: AnalyticsTopEvent[];
};

/** Raw page-view record. Session IDs are irreversibly hashed before insertion. */
export type AnalyticsPageView = {
	id: string;
	path: string;
	referrer?: string | null;
	country?: string | null;
	device?: string | null;
	browser?: string | null;
	sessionId: string;
	timestamp: Date;
};

/** Raw custom-event record. Properties contain serialized JSON. */
export type AnalyticsCustomEvent = {
	id: string;
	name: string;
	path: string;
	properties?: string | null;
	sessionId: string;
	timestamp: Date;
};

/** Literal matchers for ordered anonymous-session funnels. Prefixes use startsWith. */
export type AnalyticsFunnelStep =
	| { type: "pageview"; path: string; match: "exact" | "prefix" }
	| { type: "event"; name: string };

/** Funnels accept 2–8 steps, at most 31 days, and a 1–1440 minute window. */
export type AnalyticsFunnelParams = Pick<
	AnalyticsRangeParams,
	"range" | "start" | "end"
> & {
	windowMinutes: number;
	steps: readonly AnalyticsFunnelStep[];
};

/** Sessions are daily anonymous identifiers; totalSessions counts first-step entrants. */
export type AnalyticsFunnelResult = {
	start: string;
	end: string;
	windowMinutes: number;
	totalSessions: number;
	convertedSessions: number;
	conversionRate: number;
	steps: {
		step: AnalyticsFunnelStep;
		sessions: number;
		/** Percentage of first-step entrants. */
		conversionRate: number;
		/** Loss from the preceding step; zero for the first step. */
		dropOff: number;
		dropOffRate: number;
	}[];
};

/** Server-owned experiment definition, explicitly enabled alongside a flag resolver. */
export type AnalyticsExperimentDefinition = {
	key: string;
	flagKey: string;
	conversionEvent: string;
	/** First-exposure window, bounded by the current UTC day. @default 1800000 */
	attributionWindowMs?: number;
};

/** Persisted first meaningful exposure; sessionId is Analytics' daily anonymous hash. */
export type AnalyticsExperimentExposure = {
	id: string;
	dedupKey: string;
	experimentKey: string;
	flagKey: string;
	configurationVersion: string;
	variant: string;
	conversionEvent: string;
	attributionWindowMs: number;
	path: string;
	sessionId: string;
	timestamp: Date;
};

/** Accepted exposure activation; ownership follows these events without renewing the first-exposure window. */
export type AnalyticsExperimentActivation = {
	id: string;
	experimentKey: string;
	sessionId: string;
	exposureKey: string;
	timestamp: Date;
};

/** Descriptive counts for a single persisted experiment configuration and variant. */
export type AnalyticsExperimentVariantReport = {
	flagKey: string;
	configurationVersion: string;
	variant: string;
	conversionEvent: string;
	attributionWindowMs: number;
	subjects: number;
	exposures: number;
	conversions: number;
	/** Converted anonymous subjects divided by exposed subjects, as a percentage. */
	conversionRate: number;
};

/** Exposure cohort report; anonymous subjects are independent on each UTC day. */
export type AnalyticsExperimentReport = {
	experimentKey: string;
	flagKey: string;
	attribution: "same-session-utc-day";
	rows: AnalyticsExperimentVariantReport[];
};

import { definePermissions, permission } from "@btst/stack/authorization";
import { z } from "zod";

/** Browser-safe permission descriptors for public ingestion and private analytics. */
export const analyticsPermissions = definePermissions("analytics", {
	events: {
		ingest: permission(z.object({ kind: z.enum(["pageview", "event"]) })),
		cleanup: permission(z.object({})),
	},
	experiments: {
		expose: permission(z.object({ experimentKey: z.string() })),
		read: permission(z.object({ experimentKey: z.string() })),
	},
	dashboard: {
		read: permission(z.object({})),
		export: permission(z.object({})),
	},
});

"use client";

import { useId } from "react";
import type { AnalyticsRangeParams } from "../../types";
import { useExperimentReport } from "@btst/plugin-analytics/client/hooks";

/** Protected experiment samples, grouped by persisted definition and variant. */
export function ExperimentReport({
	experimentKey,
	params,
}: {
	experimentKey: string;
	params: AnalyticsRangeParams;
}) {
	const titleId = useId();
	const { data, isPending, isFetching, isError, refetch } = useExperimentReport(
		{
			...params,
			experimentKey,
		},
	);
	return (
		<section
			className="analytics-table-section"
			aria-labelledby={titleId}
			aria-busy={isFetching}
		>
			<div className="analytics-section-heading">
				<h2 id={titleId}>Experiment: {experimentKey}</h2>
				<span>Descriptive conversion report</span>
			</div>
			{isError ? (
				<div role="alert">
					<p>
						Experiment report unavailable. Check your access and configuration.
					</p>
					<button type="button" onClick={() => void refetch()}>
						Try again
					</button>
				</div>
			) : isPending ? (
				<p role="status">Loading experiment samples…</p>
			) : data ? (
				<>
					<p className="analytics-note">
						Attribution stays within one anonymous session and UTC day. Only
						conversions after exposure and within the listed window count. Each
						subject converts at most once per definition.
					</p>
					<div className="analytics-table-scroll">
						<table aria-label={`Variant conversions for ${experimentKey}`}>
							<thead>
								<tr>
									<th scope="col">Variant</th>
									<th scope="col">Flag</th>
									<th scope="col">Definition</th>
									<th scope="col">Conversion event</th>
									<th scope="col">Subjects</th>
									<th scope="col">Exposures</th>
									<th scope="col">Conversions</th>
									<th scope="col">Rate</th>
									<th scope="col">Window</th>
								</tr>
							</thead>
							<tbody>
								{data.rows.length ? (
									data.rows.map((row) => (
										<tr key={`${row.configurationVersion}:${row.variant}`}>
											<th scope="row" className="analytics-path">
												{row.variant}
											</th>
											<td className="analytics-path">{row.flagKey}</td>
											<td>
												<code title={row.configurationVersion}>
													{row.configurationVersion.slice(0, 12)}
												</code>
											</td>
											<td className="analytics-path">{row.conversionEvent}</td>
											<td>{row.subjects}</td>
											<td>{row.exposures}</td>
											<td>{row.conversions}</td>
											<td>{row.conversionRate.toFixed(1)}%</td>
											<td>{row.attributionWindowMs / 60000} min</td>
										</tr>
									))
								) : (
									<tr>
										<td colSpan={9}>No experiment exposures in this range.</td>
									</tr>
								)}
							</tbody>
						</table>
					</div>
					<p className="analytics-note">
						Definition changes stay separate. These observations do not
						establish statistical significance or verify purchases.
					</p>
				</>
			) : null}
		</section>
	);
}

"use client";

import { useState, type FormEvent } from "react";
import { PermissionAccess, useStack } from "@btst/stack/context";
import { analyticsPermissions } from "../../permissions";
import type {
	AnalyticsFunnelParams,
	AnalyticsFunnelStep,
	AnalyticsRangeParams,
} from "../../types";
import { ANALYTICS_PLUGIN_ID } from "../constants";
import { useFunnelReport } from "@btst/plugin-analytics/client/hooks";

const number = new Intl.NumberFormat("en");

export function FunnelReport({ range }: { range: AnalyticsRangeParams }) {
	const [steps, setSteps] = useState<AnalyticsFunnelStep[]>([
		{ type: "pageview", path: "/", match: "exact" },
		{ type: "event", name: "purchase" },
	]);
	const [windowMinutes, setWindowMinutes] = useState("30");
	const [request, setRequest] = useState<AnalyticsFunnelParams | null>(null);
	const [exporting, setExporting] = useState(false);
	const [exportError, setExportError] = useState("");
	const report = useFunnelReport(request);
	const { plugins } = useStack();
	const api = plugins?.[ANALYTICS_PLUGIN_ID]?.api;

	function updateSteps(next: AnalyticsFunnelStep[]) {
		setSteps(next);
		setRequest(null);
		setExportError("");
	}

	function run(event: FormEvent) {
		event.preventDefault();
		const next = { ...range, steps, windowMinutes: Number(windowMinutes) };
		setExportError("");
		if (JSON.stringify(next) === JSON.stringify(request)) void report.refetch();
		else setRequest(next);
	}

	async function exportCSV() {
		if (!request) return;
		setExporting(true);
		setExportError("");
		try {
			const headers = new Headers(api?.browserHeaders);
			headers.set("content-type", "application/json");
			const response = await fetch(
				`${api?.baseURL ?? ""}${(api?.basePath ?? "/api/data").replace(/\/$/, "")}/analytics/funnel/export`,
				{
					method: "POST",
					headers,
					credentials: api?.credentials ?? "same-origin",
					body: JSON.stringify(request),
				},
			);
			if (!response.ok) throw new Error("Export failed");
			const url = URL.createObjectURL(await response.blob());
			const link = document.createElement("a");
			link.href = url;
			link.download = "analytics-funnel.csv";
			link.click();
			setTimeout(() => URL.revokeObjectURL(url), 1000);
		} catch {
			setExportError(
				"Funnel could not be exported. Check your export access and try again.",
			);
		} finally {
			setExporting(false);
		}
	}

	return (
		<section
			className="analytics-table-section analytics-funnel"
			aria-labelledby="analytics-funnel-title"
		>
			<div className="analytics-section-heading">
				<h2 id="analytics-funnel-title">Conversion funnel</h2>
				<span>Ordered steps · selected UTC date range</span>
			</div>
			<p className="analytics-note">
				Count each anonymous session once. Steps must happen in order within one
				UTC day. Choose up to 31 days.
			</p>
			<form onSubmit={run} className="analytics-funnel-form">
				{steps.map((step, index) => (
					<fieldset key={index} className="analytics-funnel-step">
						<legend>Step {index + 1}</legend>
						<label>
							Type
							<select
								value={step.type}
								onChange={(event) =>
									updateSteps(
										steps.map((current, position) =>
											position === index
												? event.target.value === "pageview"
													? { type: "pageview", path: "/", match: "exact" }
													: { type: "event", name: "" }
												: current,
										),
									)
								}
							>
								<option value="pageview">Page view</option>
								<option value="event">Custom event</option>
							</select>
						</label>
						{step.type === "pageview" ? (
							<>
								<label>
									Path
									<input
										value={step.path}
										required
										maxLength={2048}
										pattern="/.*"
										onChange={(event) =>
											updateSteps(
												steps.map((current, position) =>
													position === index
														? { ...step, path: event.target.value }
														: current,
												),
											)
										}
									/>
								</label>
								<label>
									Match
									<select
										value={step.match}
										onChange={(event) =>
											updateSteps(
												steps.map((current, position) =>
													position === index
														? {
																...step,
																match: event.target.value as "exact" | "prefix",
															}
														: current,
												),
											)
										}
									>
										<option value="exact">Exact path</option>
										<option value="prefix">Path prefix</option>
									</select>
								</label>
							</>
						) : (
							<label>
								Event name
								<input
									value={step.name}
									required
									maxLength={100}
									onChange={(event) =>
										updateSteps(
											steps.map((current, position) =>
												position === index
													? { ...step, name: event.target.value }
													: current,
											),
										)
									}
								/>
							</label>
						)}
						<button
							type="button"
							disabled={steps.length <= 2}
							aria-label={`Remove step ${index + 1}`}
							onClick={() =>
								updateSteps(steps.filter((_, position) => position !== index))
							}
						>
							Remove
						</button>
					</fieldset>
				))}
				<div className="analytics-funnel-actions">
					<button
						type="button"
						disabled={steps.length >= 8}
						onClick={() => updateSteps([...steps, { type: "event", name: "" }])}
					>
						Add step
					</button>
					<label>
						Conversion window (minutes)
						<input
							type="number"
							required
							min={1}
							max={1440}
							step={1}
							value={windowMinutes}
							onChange={(event) => {
								setWindowMinutes(event.target.value);
								setRequest(null);
							}}
						/>
					</label>
					<button type="submit" disabled={report.isFetching}>
						{report.isFetching ? "Running funnel…" : "Run funnel"}
					</button>
					<PermissionAccess
						permission={analyticsPermissions.dashboard.export({})}
					>
						<button
							type="button"
							disabled={
								!request ||
								!report.data ||
								!!report.error ||
								report.isFetching ||
								exporting
							}
							onClick={() => {
								void exportCSV();
							}}
						>
							{exporting ? "Exporting funnel…" : "Export funnel CSV"}
						</button>
					</PermissionAccess>
				</div>
			</form>
			{report.error && (
				<p role="alert" className="analytics-error">
					{report.error.message}
				</p>
			)}
			{exportError && (
				<p role="alert" className="analytics-error">
					{exportError}
				</p>
			)}
			{report.data && !report.error && (
				<div aria-live="polite" aria-busy={report.isFetching}>
					<p>
						<strong>
							{number.format(report.data.convertedSessions)} of{" "}
							{number.format(report.data.totalSessions)}
						</strong>{" "}
						sessions completed all steps ·{" "}
						{report.data.conversionRate.toFixed(1)}% conversion
					</p>
					{report.data.totalSessions === 0 && (
						<p role="status">
							No sessions matched the first step in this range.
						</p>
					)}
					<div className="analytics-table-scroll">
						<table>
							<caption className="analytics-sr-only">
								Ordered funnel results. Conversion is the share of sessions
								entering step 1; drop-off is from the previous step.
							</caption>
							<thead>
								<tr>
									<th scope="col">Step</th>
									<th scope="col">Sessions</th>
									<th scope="col">Conversion</th>
									<th scope="col">Drop-off</th>
								</tr>
							</thead>
							<tbody>
								{report.data.steps.map((result, index) => (
									<tr key={index}>
										<th scope="row">
											{index + 1}.{" "}
											{result.step.type === "pageview"
												? `${result.step.path}${result.step.match === "prefix" ? " (prefix)" : ""}`
												: result.step.name}
										</th>
										<td>{number.format(result.sessions)}</td>
										<td>{result.conversionRate.toFixed(1)}%</td>
										<td>
											{index === 0
												? "—"
												: `${number.format(result.dropOff)} (${result.dropOffRate.toFixed(1)}%)`}
										</td>
									</tr>
								))}
							</tbody>
						</table>
					</div>
				</div>
			)}
		</section>
	);
}

"use client";

import { useState, type FormEvent } from "react";
import { useRegisterPageAIContext } from "@btst/stack/page-context";
import { PermissionAccess, useStack } from "@btst/stack/context";
import { analyticsPermissions } from "../../../permissions";
import type { AnalyticsRangeParams } from "../../../types";
import { TrafficChart } from "../traffic-chart";
import { FunnelReport } from "../funnel-report";
import { useRealtimeVisitors, useSuspenseDashboardStats } from "@btst/plugin-analytics/client/hooks";
import { ANALYTICS_PLUGIN_ID } from "../../constants";
import { ExperimentReport } from "../experiment-report";

const number = new Intl.NumberFormat("en");
const presets = [
	{ value: "today", label: "Today" },
	{ value: "7d", label: "7 days" },
	{ value: "30d", label: "30 days" },
] as const;

function Sparkline({ values }: { values: number[] }) {
	const max = Math.max(1, ...values);
	return (
		<svg className="analytics-sparkline" viewBox="0 0 96 28" aria-hidden="true">
			<polyline
				fill="none"
				stroke="currentColor"
				strokeWidth="2"
				points={values
					.map(
						(value, index) =>
							`${(index * 96) / Math.max(1, values.length - 1)},${26 - (value / max) * 24}`,
					)
					.join(" ")}
			/>
		</svg>
	);
}

/** Dynamic dashboard; all displayed counts come from the authenticated API. */
export function AnalyticsDashboardPage({
	experiments = [],
}: {
	experiments?: string[];
} = {}) {
	const [params, setParams] = useState<AnalyticsRangeParams>({ range: "7d" });
	const [custom, setCustom] = useState(false);
	const [start, setStart] = useState(() =>
		new Date(Date.now() - 6 * 86400000).toISOString().slice(0, 10),
	);
	const [end, setEnd] = useState(() => new Date().toISOString().slice(0, 10));
	const [rangeError, setRangeError] = useState("");
	const [exportError, setExportError] = useState("");
	const [exporting, setExporting] = useState(false);
	const { data: stats, isFetching } = useSuspenseDashboardStats(params);
	const realtime = useRealtimeVisitors();
	const { plugins } = useStack();
	const api = plugins?.[ANALYTICS_PLUGIN_ID]?.api;
	useRegisterPageAIContext({
		routeName: "analytics-dashboard",
		pageDescription: JSON.stringify({
			page: "Read-only Analytics dashboard summary. No mutation tools are available.",
			range: params,
			uniqueVisitors: stats.uniqueVisitors,
			pageViews: stats.pageViews,
			bounceRate: stats.bounceRate,
			sessionDurationSeconds: stats.sessionDuration,
			realtimeVisitors: realtime.data?.visitors,
		}),
	});

	function applyRange(event: FormEvent) {
		event.preventDefault();
		if (!start || !end || start > end) {
			setRangeError("Choose a start date on or before the end date.");
			return;
		}
		if (Date.parse(end) - Date.parse(start) > 366 * 86400000) {
			setRangeError("Choose a range of 366 days or fewer.");
			return;
		}
		setRangeError("");
		setParams({ range: "custom", start, end });
	}

	async function exportCSV() {
		setExporting(true);
		setExportError("");
		try {
			const query = new URLSearchParams();
			for (const [key, value] of Object.entries(params))
				if (value !== undefined) query.set(key, String(value));
			const url = `${api?.baseURL ?? ""}${(api?.basePath ?? "/api/data").replace(/\/$/, "")}/analytics/export?${query}`;
			const response = await fetch(url, {
				headers: api?.browserHeaders,
				credentials: api?.credentials ?? "same-origin",
			});
			if (!response.ok) throw new Error("Export failed");
			const download = URL.createObjectURL(await response.blob());
			const link = document.createElement("a");
			link.href = download;
			link.download = "analytics-events.csv";
			link.click();
			setTimeout(() => URL.revokeObjectURL(download), 1000);
		} catch {
			setExportError(
				"Events could not be exported. Check your export access and try again.",
			);
		} finally {
			setExporting(false);
		}
	}

	const duration = `${Math.floor(stats.sessionDuration / 60)}m ${Math.round(stats.sessionDuration % 60)}s`;
	return (
		<main
			className="analytics-dashboard"
			data-testid="analytics-dashboard"
			aria-busy={isFetching}
		>
			<header className="analytics-header">
				<div>
					<h1>Analytics</h1>
					<p>Understand how people use your site.</p>
				</div>
				<div className="analytics-live" aria-live="polite">
					{realtime.isError ? (
						"Live count unavailable"
					) : realtime.data ? (
						<>
							<strong>{number.format(realtime.data.visitors)}</strong> active in
							the last 5 minutes
						</>
					) : (
						"Loading live count…"
					)}
				</div>
			</header>
			<div className="analytics-toolbar">
				<div className="analytics-ranges" role="group" aria-label="Date range">
					{presets.map((preset) => (
						<button
							type="button"
							key={preset.value}
							aria-pressed={!custom && params.range === preset.value}
							onClick={() => {
								setCustom(false);
								setRangeError("");
								setParams({ range: preset.value });
							}}
						>
							{preset.label}
						</button>
					))}
					<button
						type="button"
						aria-pressed={custom}
						onClick={() => setCustom(true)}
					>
						Custom
					</button>
				</div>
				<PermissionAccess
					permission={analyticsPermissions.dashboard.export({})}
				>
					<button
						type="button"
						disabled={exporting}
						onClick={() => {
							void exportCSV();
						}}
					>
						{exporting ? "Exporting…" : "Export CSV"}
					</button>
				</PermissionAccess>
			</div>
			{custom && (
				<form className="analytics-custom-range" onSubmit={applyRange}>
					<label>
						Start date
						<input
							type="date"
							value={start}
							max={end || undefined}
							onChange={(event) => setStart(event.target.value)}
							required
						/>
					</label>
					<label>
						End date
						<input
							type="date"
							value={end}
							min={start || undefined}
							onChange={(event) => setEnd(event.target.value)}
							required
						/>
					</label>
					<button type="submit">Apply dates</button>
					<span>Dates use UTC.</span>
				</form>
			)}
			{rangeError && (
				<p role="alert" className="analytics-error">
					{rangeError}
				</p>
			)}
			{exportError && (
				<p role="alert" className="analytics-error">
					{exportError}
				</p>
			)}
			<dl className="analytics-metrics">
				<div>
					<dt>Unique visitors</dt>
					<dd>{number.format(stats.uniqueVisitors)}</dd>
				</div>
				<div>
					<dt>Page views</dt>
					<dd>{number.format(stats.pageViews)}</dd>
				</div>
				<div>
					<dt>Bounce rate</dt>
					<dd>{stats.bounceRate.toFixed(1)}%</dd>
				</div>
				<div>
					<dt>Session duration</dt>
					<dd>{duration}</dd>
				</div>
			</dl>
			{stats.pageViews === 0 && (
				<div className="analytics-empty" role="status">
					<h2>No page views in this range</h2>
					<p>
						Visit a tracked page or choose another date range. Custom events
						appear below.
					</p>
				</div>
			)}
			<TrafficChart page="analyticsDashboard" series={stats.series} />
			<PermissionAccess permission={analyticsPermissions.dashboard.read({})}>
				<FunnelReport key={JSON.stringify(params)} range={params} />
			</PermissionAccess>
			<section
				className="analytics-table-section"
				aria-labelledby="analytics-pages-title"
			>
				<div className="analytics-section-heading">
					<h2 id="analytics-pages-title">Top pages</h2>
					<span>Most viewed paths</span>
				</div>
				<div className="analytics-table-scroll">
					<table>
						<thead>
							<tr>
								<th scope="col">Page</th>
								<th scope="col">Visitors</th>
								<th scope="col">Page views</th>
								<th scope="col">Trend</th>
							</tr>
						</thead>
						<tbody>
							{stats.topPages.length ? (
								stats.topPages.map((page) => (
									<tr key={page.path}>
										<th scope="row" className="analytics-path">
											{page.path}
										</th>
										<td>{number.format(page.visitors)}</td>
										<td>{number.format(page.views)}</td>
										<td>
											<Sparkline values={page.trend} />
											<span className="analytics-sr-only">
												{page.trend.join(", ")} page views by day
											</span>
										</td>
									</tr>
								))
							) : (
								<tr>
									<td colSpan={4}>No page traffic in this range.</td>
								</tr>
							)}
						</tbody>
					</table>
				</div>
			</section>
			<div className="analytics-bottom-tables">
				<section
					className="analytics-table-section"
					aria-labelledby="analytics-referrers-title"
				>
					<div className="analytics-section-heading">
						<h2 id="analytics-referrers-title">Top referrers</h2>
						<span>Where visitors came from</span>
					</div>
					<div className="analytics-table-scroll">
						<table>
							<thead>
								<tr>
									<th scope="col">Source</th>
									<th scope="col">Page views</th>
								</tr>
							</thead>
							<tbody>
								{stats.topReferrers.length ? (
									stats.topReferrers.map((referrer) => (
										<tr key={referrer.referrer}>
											<th scope="row" className="analytics-path">
												{referrer.referrer || "Direct"}
											</th>
											<td>{number.format(referrer.views)}</td>
										</tr>
									))
								) : (
									<tr>
										<td colSpan={2}>No referrers in this range.</td>
									</tr>
								)}
							</tbody>
						</table>
					</div>
				</section>
				<section
					className="analytics-table-section"
					aria-labelledby="analytics-events-title"
				>
					<div className="analytics-section-heading">
						<h2 id="analytics-events-title">Top custom events</h2>
						<span>Actions visitors took</span>
					</div>
					<div className="analytics-table-scroll">
						<table>
							<thead>
								<tr>
									<th scope="col">Event</th>
									<th scope="col">Count</th>
								</tr>
							</thead>
							<tbody>
								{stats.topEvents.length ? (
									stats.topEvents.map((event) => (
										<tr key={event.name}>
											<th scope="row" className="analytics-path">
												{event.name}
											</th>
											<td>{number.format(event.count)}</td>
										</tr>
									))
								) : (
									<tr>
										<td colSpan={2}>No custom events in this range.</td>
									</tr>
								)}
							</tbody>
						</table>
					</div>
				</section>
			</div>
			{experiments.map((experimentKey) => (
				<PermissionAccess
					key={experimentKey}
					permission={analyticsPermissions.experiments.read({ experimentKey })}
				>
					<ExperimentReport experimentKey={experimentKey} params={params} />
				</PermissionAccess>
			))}
			<p className="analytics-note">
				Anonymous sessions are held in memory. No analytics cookies are created.
				Single-page sessions have a recorded duration of zero.
			</p>
		</main>
	);
}

"use client";

import { lazy, useEffect, useState } from "react";
import { ComposedRoute } from "@btst/stack/client/components";
import { analyticsPermissions } from "../../../permissions";

const Dashboard = lazy(() =>
	import("./dashboard-page.internal").then((module) => ({
		default: module.AnalyticsDashboardPage,
	})),
);

function Loading() {
	return (
		<div className="analytics-dashboard" role="status" aria-live="polite">
			<h1>Analytics</h1>
			<p>Loading traffic…</p>
		</div>
	);
}

function BrowserDashboard({ experiments }: { experiments?: string[] }) {
	const [mounted, setMounted] = useState(false);
	useEffect(() => setMounted(true), []);
	return mounted ? <Dashboard experiments={experiments} /> : <Loading />;
}

function ErrorState({
	resetErrorBoundary,
}: {
	resetErrorBoundary: () => void;
}) {
	return (
		<div className="analytics-dashboard" role="alert">
			<h1>Analytics unavailable</h1>
			<p>Traffic could not be loaded. Check your access and try again.</p>
			<button type="button" onClick={resetErrorBoundary}>
				Try again
			</button>
		</div>
	);
}

/** Dashboard route with authorization, loading and error boundaries. */
export function AnalyticsDashboardPageComponent({
	experiments,
}: {
	experiments?: string[];
} = {}) {
	return (
		<ComposedRoute
			path="/analytics"
			permission={analyticsPermissions.dashboard.read({})}
			PageComponent={BrowserDashboard}
			props={{ experiments }}
			ErrorComponent={ErrorState}
			LoadingComponent={Loading}
			onError={(error) => console.error("Analytics dashboard failed:", error)}
		/>
	);
}

"use client";

import { usePluginOverrides } from "@btst/stack/context";
import { ANALYTICS_PLUGIN_ID } from "../constants";
import type {
	AnalyticsPluginOverrides,
	AnalyticsTrafficChartProps,
} from "../overrides";

const number = new Intl.NumberFormat("en");
const dateLabel = (date: string) =>
	new Intl.DateTimeFormat("en", {
		month: "short",
		day: "numeric",
		timeZone: "UTC",
	}).format(new Date(date));

export function TrafficChart({
	page,
	...props
}: AnalyticsTrafficChartProps & { page?: "analyticsDashboard" }) {
	return page ? (
		<ScopedTrafficChart page={page} {...props} />
	) : (
		<DefaultTrafficChart {...props} />
	);
}

function ScopedTrafficChart({
	page,
	...props
}: AnalyticsTrafficChartProps & { page: "analyticsDashboard" }) {
	const { pageOverrides } =
		usePluginOverrides<AnalyticsPluginOverrides>(ANALYTICS_PLUGIN_ID);
	const Component =
		(page ? pageOverrides?.[page]?.TrafficChart : undefined) ??
		DefaultTrafficChart;
	return <Component {...props} />;
}

function DefaultTrafficChart({ series }: AnalyticsTrafficChartProps) {
	const max = Math.max(1, ...series.map((point) => point.pageViews));
	const points = series.map(
		(point, index) =>
			`${(index * 960) / Math.max(1, series.length - 1)},${180 - (point.pageViews / max) * 160}`,
	);
	return (
		<section
			className="analytics-traffic"
			aria-labelledby="analytics-traffic-title"
		>
			<div className="analytics-section-heading">
				<h2 id="analytics-traffic-title">Traffic over time</h2>
				<span>Page views per day · UTC</span>
			</div>
			<svg
				className="analytics-chart"
				viewBox="-5 0 970 200"
				role="img"
				aria-label={`Daily page views from ${series[0]?.date ?? "start"} to ${series.at(-1)?.date ?? "end"}. Peak ${max} page views.`}
			>
				<line
					x1="0"
					x2="960"
					y1="180"
					y2="180"
					className="analytics-chart-rule"
				/>
				{points.length > 0 && (
					<>
						<polygon
							points={`0,180 ${points.join(" ")} ${points.length > 1 ? "960" : "0"},180`}
							className="analytics-chart-area"
						/>
						<polyline
							points={points.join(" ")}
							fill="none"
							stroke="currentColor"
							strokeWidth="3"
							vectorEffect="non-scaling-stroke"
						/>
						{series.length === 1 && (
							<circle
								cx="0"
								cy={180 - (series[0]!.pageViews / max) * 160}
								r="4"
								fill="currentColor"
							/>
						)}
					</>
				)}
			</svg>
			<div className="analytics-chart-labels">
				<span>{series[0] ? dateLabel(series[0].date) : ""}</span>
				<span>{series.at(-1) ? dateLabel(series.at(-1)!.date) : ""}</span>
			</div>
			<details className="analytics-chart-data">
				<summary>View daily counts</summary>
				<div className="analytics-table-scroll">
					<table>
						<thead>
							<tr>
								<th scope="col">Date (UTC)</th>
								<th scope="col">Page views</th>
								<th scope="col">Visitors</th>
							</tr>
						</thead>
						<tbody>
							{series.map((point) => (
								<tr key={point.date}>
									<th scope="row">{point.date}</th>
									<td>{number.format(point.pageViews)}</td>
									<td>{number.format(point.visitors)}</td>
								</tr>
							))}
						</tbody>
					</table>
				</div>
			</details>
		</section>
	);
}

import type { ComponentType } from "react";
import type { AnalyticsSeriesPoint } from "../types";

/** Traffic series supplied by the built-in dashboard. */
export interface AnalyticsTrafficChartProps {
	/** Daily page view and visitor totals. */
	series: AnalyticsSeriesPoint[];
}

/** Presentation customization for built-in analytics pages. */
export interface AnalyticsPluginOverrides {
	/** Replace only the dashboard chart, retaining filters, metrics, and tables. */
	pageOverrides?: {
		analyticsDashboard?: {
			TrafficChart?: ComponentType<AnalyticsTrafficChartProps>;
		};
	};
}
